import { app } from 'electron';
import path from 'node:path';

export function appIconPath(): string {
  return app.isPackaged
    ? path.join(process.resourcesPath, 'icon.png')
    : path.join(__dirname, '..', 'build', 'icon.png');
}

// distinct icon for the Player View so capture tools / taskbars can tell
// it apart from the GM window (generated by scripts/build-icons.mjs)
export function playerIconPath(): string {
  return app.isPackaged
    ? path.join(process.resourcesPath, 'icon-player.png')
    : path.join(__dirname, '..', 'build', 'icon-player.png');
}
